// Loaded original HEADS before linking: sibling member discovery and full BLinker observations.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.awt.geom.*;
public class StemImageBeamTargetsProbe extends StemImageSourcesProbe {
 private final Object book;public StemImageBeamTargetsProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static String point(Object p){Point2D x=(Point2D)p;return "["+x.getX()+","+x.getY()+"]";}
 static String beam(Object b)throws Exception{return "{\"bounds\":"+rect(call(b,"getBounds"))+",\"median\":"+line(call(b,"getMedian"))+",\"height\":"+call(b,"getHeight")+"}";}
 static String members(Collection<?> bs)throws Exception{List<String>r=new ArrayList<>();for(Object b:bs)r.add(beam(b));return "["+String.join(",",r)+"]";}
 static String bLinker(Object l)throws Exception{Object s=get(l,"stump"),side=get(l,"hSide");return "{\"side\":"+(side==null?"null":"\""+side+"\"")+",\"reference\":"+point(call(l,"getReferencePoint"))+",\"stump\":"+(s==null?"null":physical(s))+",\"anchor\":"+get(l,"isAnchor")+"}";}
 static String control(Object bl,Object p,String name,Point2D at,int dx)throws Exception{set(p,"maxBeamSideDx",dx);return "{\"name\":\""+name+"\",\"members\":"+members((List<?>)call(get(bl,"beamGroup"),"getMembers"))+",\"point\":"+point(at)+",\"max_beam_side_dx\":"+dx+",\"selected\":"+members((List<?>)call(bl,"getSiblingBeamsAt",at))+"}";}
 public void process(){try{
 Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");List<String>ss=new ArrayList<>(),controls=new ArrayList<>();Object firstBL=null,firstP=null;int corners=0,selected=0,catalogCount=0;
 for(Object sys:(List<?>)call(sheet,"getSystems")){Object retr=inspect(sys,sheet),p=get(retr,"params");List<String>bs=new ArrayList<>(),cases=new ArrayList<>();for(Object b:(List<?>)get(retr,"systemBeams")){Object bl=call(b,"getLinker");if(firstBL==null){firstBL=bl;firstP=p;}List<String>ls=new ArrayList<>();for(Object l:(List<?>)get(bl,"allBLinkers")){ls.add(bLinker(l));catalogCount++;}bs.add("{\"beam\":"+beam(b)+",\"seed_area_path\":"+path(call(bl,"getSeedArea"))+",\"stumps\":"+glyphs((Collection<?>)get(bl,"stumps"))+",\"all_blinkers\":["+String.join(",",ls)+"]}");}
 for(Object head:(List<?>)get(retr,"systemHeads"))for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Object c=call(call(head,"getLinker"),"getCornerLinker",en("util.HorizontalSide",side),en("util.VerticalSide",vert)),target=get(c,"targetBeam");boolean veto=call(head,"getShape").toString().equals("NOTEHEAD_VOID")&&vert.equals(side.equals("LEFT")?"TOP":"BOTTOM");String at="null",siblings="[]";if(target!=null&&!veto){Point2D hit=(Point2D)Class.forName("org.audiveris.omr.math.LineUtil").getMethod("intersection",Line2D.class,Line2D.class).invoke(null,call(target,"getMedian"),get(c,"theoLine"));at=point(hit);List<?> list=(List<?>)call(call(target,"getLinker"),"getSiblingBeamsAt",hit);siblings=members(list);selected+=list.size();}corners++;cases.add("{\"head_bounds\":"+rect(call(head,"getBounds"))+",\"shape\":\""+call(head,"getShape")+"\",\"side\":\""+side+"\",\"vertical\":\""+vert+"\",\"target_beam\":"+(target==null?"null":beam(target))+",\"void_side_veto\":"+veto+",\"intersection\":"+at+",\"selected_sibling_members\":"+siblings+"}");}
 ss.add("{\"system\":"+call(sys,"getId")+",\"max_beam_side_dx\":"+get(p,"maxBeamSideDx")+",\"beam_catalog\":["+String.join(",",bs)+"],\"cases\":["+String.join(",",cases)+"]}");}
 Line2D m=(Line2D)get(firstBL,"median");for(int dx:new int[]{0,3})for(String side:new String[]{"left","right"}){double edge=side.equals("left")?m.getX1()-dx:m.getX2()+dx;for(double x:new double[]{Math.nextDown(edge),edge,Math.nextUp(edge)})controls.add(control(firstBL,firstP,side+"-"+dx+"-"+x,new Point2D.Double(x,m.getY1()),dx));}
 controls.add(control(firstBL,firstP,"outside",new Point2D.Double(-100,0),3));
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"original_phase\":\"inspectStems_before_linkStems_and_finalizeStems\",\"corners\":"+corners+",\"selected_sibling_member_occurrences\":"+selected+",\"observed_all_blinkers\":"+catalogCount+",\"systems\":["+String.join(",",ss)+"],\"controls\":["+String.join(",",controls)+"]}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
